/**
 * distribution.ts — public download distribution abstraction for the AetherOS website.
 *
 * Security boundaries (load-bearing, covered by scripts/distribution.test.mjs):
 * - Download URLs NEVER come from user input. They come from the trusted release
 *   manifest (`static/api/releases/*.json`, generated by
 *   scripts/generate-download-manifest.mjs from verified pipeline inputs).
 * - `resolveArtifact()` allowlists (platform, arch, kind) against the manifest
 *   contents. Unknown values return null — no URL is ever constructed from them.
 * - `artifactUrl()` only returns URLs already present in the manifest entry AND
 *   rooted at the manifest's own `distributionBaseUrl` (https). Anything else
 *   returns null instead of a redirect target.
 * - This module MUST NOT import secrets, tokens, credentials, or private
 *   repository URLs. The manifest is the only data source.
 */

export const DISTRIBUTION_SCHEMA_VERSION = 1;

// Allowlisted dimensions. The manifest may only use these keys; the generator
// rejects anything else, and resolveArtifact() rejects anything else at runtime.
export const KNOWN_PLATFORMS = ["windows", "macos", "linux"] as const;
export const KNOWN_ARCHES = ["x64", "arm64"] as const;
export const KNOWN_KINDS = [
  "installer",
  "msi",
  "portable",
  "dmg",
  "zip",
  "appimage",
  "deb",
  "rpm",
] as const;

export type Platform = (typeof KNOWN_PLATFORMS)[number];
export type Arch = (typeof KNOWN_ARCHES)[number];
export type ArtifactKind = (typeof KNOWN_KINDS)[number];

export interface ReleaseArtifact {
  kind: ArtifactKind;
  file: string;
  url: string;
  sha256: string;
  size: number;
}

export interface ReleaseManifest {
  schemaVersion: number;
  product: string;
  version: string;
  channel: string;
  releaseDate: string;
  distributionBaseUrl: string;
  sourceCommit: string;
  workflowRun: string;
  signed: boolean;
  productionReady: boolean;
  signatures: Record<string, string>;
  platforms: Record<string, Record<string, ReleaseArtifact[]>>;
}

const SHA256_RE = /^[0-9a-f]{64}$/i;

export function isPlatform(v: string): v is Platform {
  return (KNOWN_PLATFORMS as readonly string[]).includes(v);
}

export function isArch(v: string): v is Arch {
  return (KNOWN_ARCHES as readonly string[]).includes(v);
}

export function isKind(v: string): v is ArtifactKind {
  return (KNOWN_KINDS as readonly string[]).includes(v);
}

/** Structural validation of a fetched manifest. Returns a human-readable error or null. */
export function validateManifest(m: unknown): string | null {
  if (!m || typeof m !== "object") return "manifest is not an object";
  const man = m as Record<string, unknown>;
  if (man.schemaVersion !== DISTRIBUTION_SCHEMA_VERSION)
    return `unsupported schemaVersion ${String(man.schemaVersion)}`;
  if (typeof man.version !== "string" || !man.version) return "missing version";
  if (typeof man.distributionBaseUrl !== "string" || !man.distributionBaseUrl.startsWith("https://"))
    return "distributionBaseUrl must be https";
  if (!man.platforms || typeof man.platforms !== "object") return "missing platforms";
  for (const [platform, arches] of Object.entries(man.platforms as Record<string, unknown>)) {
    if (!isPlatform(platform)) return `unknown platform ${platform}`;
    if (!arches || typeof arches !== "object") return `bad arches for ${platform}`;
    for (const [arch, list] of Object.entries(arches as Record<string, unknown>)) {
      if (!isArch(arch)) return `unknown arch ${arch}`;
      if (!Array.isArray(list) || list.length === 0) return `empty artifact list for ${platform}/${arch}`;
      for (const a of list as Record<string, unknown>[]) {
        if (!isKind(String(a.kind))) return `unknown kind ${String(a.kind)}`;
        if (typeof a.file !== "string" || a.file.includes("..") || a.file.includes("/") || a.file.includes("\\"))
          return `unsafe filename ${String(a.file)}`;
        if (typeof a.url !== "string" || !a.url.startsWith(man.distributionBaseUrl as string))
          return `url not rooted at distributionBaseUrl for ${String(a.file)}`;
        if (typeof a.sha256 !== "string" || !SHA256_RE.test(a.sha256))
          return `bad sha256 for ${String(a.file)}`;
        if (typeof a.size !== "number" || !Number.isInteger(a.size) || a.size <= 0)
          return `bad size for ${String(a.file)}`;
      }
    }
  }
  return null;
}

/**
 * Allowlisted artifact lookup. Returns the manifest entry or null.
 * Never throws on unknown input; never constructs a URL from input.
 */
export function resolveArtifact(
  manifest: ReleaseManifest,
  platform: string,
  arch: string,
  kind: string,
): ReleaseArtifact | null {
  if (!isPlatform(platform) || !isArch(arch) || !isKind(kind)) return null;
  const list = manifest.platforms[platform]?.[arch];
  if (!Array.isArray(list)) return null;
  return list.find((a) => a.kind === kind) ?? null;
}

/** Returns the download URL for a manifest entry, or null if it fails the base-URL check. */
export function artifactUrl(manifest: ReleaseManifest, artifact: ReleaseArtifact): string | null {
  if (!artifact.url.startsWith(manifest.distributionBaseUrl)) return null;
  if (!manifest.distributionBaseUrl.startsWith("https://")) return null;
  return artifact.url;
}

export function formatBytes(size: number): string {
  if (size >= 1 << 30) return `${(size / (1 << 30)).toFixed(1)} GB`;
  if (size >= 1 << 20) return `${(size / (1 << 20)).toFixed(1)} MB`;
  return `${size} B`;
}
